mapper.select:
${params.sqlCol} from  adm.trs_mth_income_industry a
where a.D_ACCT = '${params.D_ACCT}'

AND ENTERPRISE_NAME like '%${params.ENTERPRISE_NAME}%'


    AND S_TRECODE = ${params.S_TRECODE}


    AND S_BELONGFLAG = '${params.S_BELONGFLAG}'

${params.orderBy}
LIMIT ${params.rows} OFFSET ${params.page}

${params.sqlCol} from  adm.trs_mth_income_industry a
where a.D_ACCT = '${params.D_ACCT}'

    AND ENTERPRISE_NAME like '%${params.ENTERPRISE_NAME}%'


    AND S_TRECODE = ${params.S_TRECODE}


    AND S_BELONGFLAG = '${params.S_BELONGFLAG}'

${params.orderBy}

select count(1) from (
${params.sqlCol} from  adm.trs_mth_income_industry a
where a.D_ACCT = '${params.D_ACCT}'

    AND ENTERPRISE_NAME like '%${params.ENTERPRISE_NAME}%'


    AND S_TRECODE = ${params.S_TRECODE}


    AND S_BELONGFLAG = '${params.S_BELONGFLAG}'

${params.orderBy}
)v

/*取每组分数高的前两个*/ ${params.sqlCol} FROM ( SELECT a.*, ROW_NUMBER() OVER (PARTITION BY INDUSTRY_NAME ORDER BY ${params.orderBy} DESC) AS rank FROM (SELECT INDUSTRY_NAME ,D_ACCT ,ENTERPRISE_CODE ,ENTERPRISE_NAME ,SUM(F_AMT_101) /${params.UNIT} AS "F_AMT_101" ,(SUM(F_AMT_101)-SUM(F_AMT_101_YEAR)) /SUM(F_AMT_101_YEAR) AS "F_AMT_101_YEAR" ,SUM(F_AMT_10101) /${params.UNIT} AS "F_AMT_10101" ,(SUM(F_AMT_10101)-SUM(F_AMT_10101_YEAR)) /SUM(F_AMT_10101_YEAR) AS "F_AMT_10101_YEAR" ,SUM(F_AMT_1010101) /${params.UNIT} AS "F_AMT_1010101" ,(SUM(F_AMT_1010101)-SUM(F_AMT_1010101_YEAR))/SUM(F_AMT_1010101_YEAR) AS "F_AMT_1010101_YEAR" ,SUM(F_AMT_1010104)/${params.UNIT} AS "F_AMT_1010104" ,(SUM(F_AMT_1010104)-SUM(F_AMT_1010104_YEAR))/SUM(F_AMT_1010104_YEAR) AS "F_AMT_1010104_YEAR" ,SUM(F_AMT_10102) /${params.UNIT} AS "F_AMT_10102" ,(SUM(F_AMT_10102)-SUM(F_AMT_10102_YEAR))/ SUM(F_AMT_10102_YEAR) AS "F_AMT_10102_YEAR" ,SUM(F_AMT_1010201) /${params.UNIT} AS "F_AMT_1010201" ,(SUM(F_AMT_1010201)-SUM(F_AMT_1010201_YEAR))/SUM(F_AMT_1010201_YEAR) AS "F_AMT_1010201_YEAR" ,SUM(F_AMT_10104) /${params.UNIT} AS "F_AMT_10104" ,(SUM(F_AMT_10104)-SUM(F_AMT_10104_YEAR))/SUM(F_AMT_10104_YEAR) AS "F_AMT_10104_YEAR" ,SUM(F_AMT_10106) /${params.UNIT} AS "F_AMT_10106" ,(SUM(F_AMT_10106)-SUM(F_AMT_10106_YEAR) )/SUM(F_AMT_10106_YEAR) AS "F_AMT_10106_YEAR" ,SUM(F_AMT_10107) /${params.UNIT} AS "F_AMT_10107" ,(SUM(F_AMT_10107)-SUM(F_AMT_10107_YEAR) )/SUM(F_AMT_10107_YEAR) AS "F_AMT_10107_YEAR" ,SUM(F_AMT_10109) /${params.UNIT} AS "F_AMT_10109" ,(SUM(F_AMT_10109)-SUM(F_AMT_10109_YEAR))/SUM(F_AMT_10109_YEAR) AS "F_AMT_10109_YEAR" ,SUM(F_AMT_10110) /${params.UNIT} AS "F_AMT_10110" ,(SUM(F_AMT_10110)-SUM(F_AMT_10110_YEAR) )/SUM(F_AMT_10110_YEAR) AS "F_AMT_10110_YEAR" ,SUM(F_AMT_10111)/${params.UNIT} AS "F_AMT_10111" ,(SUM(F_AMT_10111)-SUM(F_AMT_10111_YEAR))/SUM(F_AMT_10111_YEAR) AS "F_AMT_10111_YEAR" ,SUM(F_AMT_10112) /${params.UNIT} AS "F_AMT_10112" ,(SUM(F_AMT_10112)-SUM(F_AMT_10112_YEAR) )/SUM(F_AMT_10112_YEAR) AS "F